<script setup>
import { computed } from 'vue'
import Icon from '../../components/Icon.vue'
import MarkdownRenderer from '../../components/MarkdownRenderer.vue'
import { sourcePosition } from '../learning/journey.js'
const props=defineProps({workspace:Object,archived:Boolean})
const emit=defineEmits(['edit-note', 'practice'])
const w=props.workspace
const localOnly=computed(()=>w.mode==='local' || w.personal.length && !w.consent || w.teachers.length && !w.teacherConsent)
const consent=computed({get:()=> (!w.personal.length || w.consent) && (!w.teachers.length || w.teacherConsent),set:v=>{w.consent=v;w.teacherConsent=v}})
const reasons={local_requested:'本轮仅本地检索，没有调用模型。',personal_consent_required:'未授权个人笔记外发，本轮仅在本地检索。',teacher_consent_required:'未授权上传或教师资料外发，本轮仅在本地检索。',model_disabled:'模型服务未启用，已返回本地结果。',model_timeout:'模型超时，执行结果待确认，不会自动重发。',network_error:'模型网络异常，不会自动重发。',context_changed:'生成期间资料或笔记本发生变化，以下保留当时的结果。',unverified_model_answer:'模型输出格式或引用未通过校验，已保留本地结果。',execution_unconfirmed:'原请求执行情况尚未确认，仅查询记录，不会再次调用模型。',tool_scope_rejected:'模型请求超出允许来源，服务端已拒绝。'}
function citation(id){const item=w.current?.citations?.find(c=>c.citation_id===id);if(item)w.citation(item)}
async function save(){const result=await w.save();if(result && !result.deleted)emit('edit-note',result.note_id)}
</script>
<template>
  <section class="notebook-chat" aria-label="笔记本助教问答">
    <div class="notebook-chat-heading"><span><Icon name="spark" :size="18" />助教问答</span><details v-if="w.runs.length" class="notebook-history"><summary>历史 · {{w.runs.length}}</summary><div><p>只读取已保存回答，不再次调用模型。</p><button v-for="run in w.runs" :key="run.request_id" :aria-pressed="w.current?.request_id===run.request_id" @click="w.view(run)">{{run.question}}<small>{{new Date(run.created_at).toLocaleString('zh-CN')}}</small></button></div></details></div>
    <p v-if="w.error" class="product-message error" role="alert">{{w.error}}</p><p v-if="w.notice" class="product-message" role="status">{{w.notice}}</p>
    <div v-if="!w.current" class="notebook-chat-welcome"><span class="notebook-assistant-icon"><Icon name="spark" :size="31" /></span><h2>把资料，变成你的理解</h2><p>选择资料，提出问题。每个引用都能打开对应原文。</p><div><button @click="w.prepare('请解释所选资料的核心概念，并举一个具体例子。')">理解核心概念<Icon name="arrow" :size="15" /></button><button @click="w.prepare('这些概念有哪些容易混淆的地方？请结合资料对比说明。')">弄清概念之间的区别<Icon name="arrow" :size="15" /></button></div></div>
    <article v-else class="notebook-answer" aria-label="已保存回答"><div class="notebook-user-question">{{w.current.question}}</div><div class="notebook-answer-meta"><Icon name="spark" :size="16" /><strong>EduAgent</strong><span>{{w.current.status==='complete'?'AI讲解':w.current.status==='uncertain'?'待确认':'本地资料反馈'}} · {{new Date(w.current.created_at).toLocaleString('zh-CN')}}</span></div><p v-if="w.current.reason" class="product-message" role="status">{{reasons[w.current.reason] || '本轮模型未完成正常回答，已保留状态与可用的本地结果。'}}<span v-if="w.current.validation_error"> 校验：{{w.current.validation_error}}</span></p><p v-if="w.current.notebook_context_stale || w.current.source_statuses?.some(s=>s.current_status!=='current')" class="product-message">笔记本或资料后来已变化。以下引用是回答时的快照，不能作为当前检索资料。</p><p v-if="w.current.answer_basis==='model_knowledge'" class="product-message">来自模型自身知识，可能有误，没有本地资料依据。</p><MarkdownRenderer number-citations :source="w.current.answer || ''" :citation-ids="(w.current.citations || []).map(c=>c.citation_id)" @citation="citation" /><div class="notebook-citations"><button v-for="(item,i) in w.current.citations || []" :key="item.citation_id" @click="w.citation(item)"><span>{{i+1}}</span><div><strong>{{item.title}}</strong><small>{{sourcePosition(item)}}</small></div><Icon name="arrow" :size="14" /></button></div><button v-if="w.current.answer && ['complete','local','stale'].includes(w.current.status) && !archived" class="product-text-button" :disabled="Boolean(w.busy)" @click="save"><Icon name="note" :size="16" />{{w.current.saved_note_id?'打开已另存笔记':'回答另存为笔记'}}</button><div class="notebook-answer-actions"><button class="product-text-button" @click="emit('practice')"><Icon name="check" :size="16" />到本笔记本练习</button></div></article>
    <div v-if="w.pendingId" class="product-message" role="status">原请求正在核对，不会自动重发。<button class="product-text-button" @click="w.load()">查询原请求</button><button class="product-text-button" @click="w.releaseUncertain()">结束等待</button></div>
    <form class="notebook-composer" @submit.prevent="w.ask()"><div class="notebook-selected-summary">本轮已选 {{w.chosen.length}} 份资料<span v-if="!w.chosen.length"> · 在左侧勾选参与问答</span></div><details v-if="w.chosen.length" class="notebook-selected-details"><summary>查看本轮使用的资料</summary><ul><li v-for="s in w.chosen" :key="s.source_type+':'+s.source_id">{{s.title}} · {{s.source_type==='personal_note'?'个人笔记':s.source_type==='uploaded_document'?'上传资料 · 未核验':s.source_type==='teaching_material'?'已确认片段':'课程资料'}}</li></ul></details><label class="sr-only" for="notebook-question">向助教提问</label><textarea id="notebook-question" v-model="w.query" rows="3" maxlength="1000" placeholder="围绕你的学习资料，问一个问题…" :disabled="archived" @keydown.ctrl.enter.prevent="w.ask()" /><div class="notebook-composer-actions"><label><span class="sr-only">处理方式</span><select v-model="w.mode" aria-label="处理方式"><option value="local">仅本地检索</option><option value="model" :disabled="!w.capabilities?.model_enabled">{{w.capabilities?.provider || 'DeepSeek'}} · AI讲解{{w.capabilities?.model_enabled?'':'（未启用）'}}</option></select></label><button class="product-primary" :disabled="Boolean(archived || w.busy || w.pendingId || !w.chosen.length || !w.query.trim())">{{w.busy==='ask'?'正在处理…':localOnly?'检索资料':'发送问题'}}<Icon name="arrow" :size="17" /></button></div><div v-if="w.mode==='model' && (w.personal.length || w.teachers.length)" class="notebook-external-consent"><label><input v-model="consent" type="checkbox" />我同意本轮将所选私人资料的相关片段发送至 {{w.capabilities?.provider || 'DeepSeek'}}</label><p>{{[...w.personal,...w.teachers].map(s=>s.title).join('、')}}。仅发送相关片段和问题，不发送完整资料或历史；下轮重新同意。未同意则只本地检索。</p></div><p class="notebook-composer-hint">先检索所选资料，再由模型结合资料与自身知识解释；模型补充与原文引用区分。Ctrl + Enter 发送。</p></form>
  </section>
</template>
